using UA.DataAccess.Interface.Common;
using UA.Entities;
using UA.Facade.DTO.Website;
using UA.Facade.Interface.Website;
using UA.Facade.Interface.Administration;
using UA.Framework.Constants;
using UA.Framework.Exceptions;
using UA.Framework.Security;
using UA.Framework.Time;
namespace UA.Facade.Implementation.Website;
public sealed class PublicWebsiteFacade(IRepository<Department> departments,IRepository<AcademicProgram> programs,
 IRepository<UA.Entities.Faculty> faculty,IRepository<Notice> notices,IRepository<WebPage> pages,IRepository<WebPageVersion> versions,IRepository<ExamEvent> exams,
 IUnitOfWork work,IUserAccessFacade access,ICurrentUser current,IClock clock):IPublicWebsiteFacade
{
 private int Actor=>current.UserId??throw new ForbiddenException();
 public async Task<WebsiteHome> HomeAsync(){var ds=await departments.ListAsync(x=>x.Status=="Active");var ps=await programs.ListAsync();var ns=await notices.ListAsync(x=>x.IsPublic&&x.PublishedAt!=null&&x.ApprovedBy!=null&&x.PublishedAt<=clock.Now);var special=await exams.ListAsync(x=>x.EventType=="Special"&&(x.Status=="Scheduled"||x.Status=="Completed"));var pp=await pages.ListAsync(x=>x.Status=="Published");var result=new List<PublicPage>();foreach(var p in pp){var v=await Latest(p);if(v!=null)result.Add(v);}return new(ds.Select(d=>{var p=ps.FirstOrDefault(x=>x.DepartmentId==d.DepartmentId);return new PublicDepartment(d.DepartmentId,d.Code,d.Name,p?.Name,p?.TotalCredits,p?.SemesterCount);}).ToArray(),ns.Select(n=>new PublicNotice(n.NoticeId,n.Title,n.Body,n.PublishedAt!.Value,ds.FirstOrDefault(d=>d.DepartmentId==n.DepartmentId)?.Name??"University")).Concat(special.Select(e=>new PublicNotice(-e.EventId,"Special retake examination",$"Examination date: {e.StartDate:dd MMM yyyy}. Eligible students should check their portal for the routine and seat plan.",e.StartDate,"Controller of Examinations"))).OrderByDescending(n=>n.Published).Take(100).ToArray(),result);}
 public async Task<IReadOnlyList<PublicFaculty>> FacultyAsync(){var ds=await departments.ListAsync(x=>x.Status=="Active");var ids=ds.Select(d=>d.DepartmentId).ToArray();return (await faculty.ListAsync(x=>x.Status=="Active"&&ids.Contains(x.DepartmentId))).OrderBy(x=>x.DepartmentId).ThenBy(x=>x.FullName).Select(x=>new PublicFaculty(x.FullName,ds.Single(d=>d.DepartmentId==x.DepartmentId).Name,x.Designation,x.Qualifications)).ToArray();}
 private async Task<PublicPage?> Latest(WebPage p){var v=(await versions.ListAsync(x=>x.PageId==p.PageId&&x.ApprovedBy!=null)).OrderByDescending(x=>x.VersionNo).FirstOrDefault();return v==null?null:new(p.PageId,p.DepartmentId,p.Slug,p.Title,v.Content,v.VersionNo);}
 public async Task<PublicPage?> PageAsync(string slug){var p=await pages.FirstAsync(x=>x.Slug==slug&&x.Status=="Published");return p==null?null:await Latest(p);}
 private async Task<bool> Global(string permission){try{await access.RequireGlobalAsync(permission);return true;}catch(ForbiddenException){return false;}}
 private async Task<bool> CanEdit(int? dept){if(dept==null)return await Global("pages.edit");var assignments=(await access.ForUserAsync(Actor)).Assignments;return assignments.Any(x=>x.DepartmentId==dept&&(x.RoleName==RoleNames.Head||x.RoleName==RoleNames.Coordinator))&&await access.AllowedAsync(Actor,"departmentpage.edit",dept);}
 private async Task<bool> CanApprove(int? dept){if(dept==null)return await Global("pages.approve");return await access.AllowedAsync(Actor,"pages.approve",dept);}
 public async Task<IReadOnlyList<PageVersionRow>> HistoryAsync(){if(!await access.AllowedAsync(Actor,"pages.edit")&&!await access.AllowedAsync(Actor,"departmentpage.edit")&&!await access.AllowedAsync(Actor,"pages.approve"))throw new ForbiddenException();var pp=await pages.ListAsync();var rr=new List<PageVersionRow>();foreach(var p in pp){if(!await CanEdit(p.DepartmentId)&&!await CanApprove(p.DepartmentId))continue;foreach(var v in await versions.ListAsync(x=>x.PageId==p.PageId))rr.Add(new(p.PageId,v.VersionId,v.VersionNo,p.Slug,p.Title,p.DepartmentId,v.Content,v.AuthorId,v.ApprovedBy,v.ChangedAt));}return rr.OrderBy(x=>x.Slug).ThenByDescending(x=>x.Version).ToArray();}
 public async Task DraftAsync(string slug,string title,int? departmentId,string content){slug=(slug??"").Trim().ToLowerInvariant();title=(title??"").Trim();if(!await CanEdit(departmentId))throw new ForbiddenException();if(slug=="site-profile"){if(departmentId!=null||title!="University profile")throw new BusinessRuleException("The university profile is central and has a fixed title.");try{UA.Facade.Rules.Website.PublicContent.Validate(System.Text.Json.JsonSerializer.Deserialize<UA.Facade.Rules.Website.SiteProfile>(content)??throw new BusinessRuleException("Invalid profile."));}catch(System.Text.Json.JsonException){throw new BusinessRuleException("Use the university profile form.");}}if(slug.Length is <1 or >100||!slug.All(c=>char.IsAsciiLetterOrDigit(c)||c=='-')||title.Length is <1 or >200||string.IsNullOrWhiteSpace(content)||content.Length>30000)throw new BusinessRuleException("Invalid slug, title or page content.");await work.ExecuteTransactionAsync(async ct=>{if(departmentId!=null&&await departments.FirstAsync(x=>x.DepartmentId==departmentId&&x.Status=="Active",ct)==null)throw new BusinessRuleException("Department unavailable.");var p=await pages.FirstAsync(x=>x.Slug==slug,ct);if(p==null){p=new WebPage{Slug=slug,Title=title,DepartmentId=departmentId,Status="Pending"};await pages.AddAsync(p,ct);await work.SaveChangesAsync(ct);}else if(p.DepartmentId!=departmentId||p.Title!=title)throw new BusinessRuleException("Existing page ownership and title are fixed; use the same values to create a new content version.");var vv=await versions.ListAsync(x=>x.PageId==p.PageId,ct);await versions.AddAsync(new WebPageVersion{PageId=p.PageId,VersionNo=vv.Count==0?1:vv.Max(x=>x.VersionNo)+1,AuthorId=Actor,ChangedAt=clock.Now,Content=content.Trim()},ct);});}
 public async Task ApproveAsync(int versionId){await work.ExecuteTransactionAsync(async ct=>{var v=await versions.FirstAsync(x=>x.VersionId==versionId,ct)??throw new NotFoundException();var p=await pages.FirstAsync(x=>x.PageId==v.PageId,ct)??throw new NotFoundException();if(!await CanApprove(p.DepartmentId))throw new ForbiddenException();if(v.AuthorId==Actor||v.ApprovedBy!=null)throw new BusinessRuleException("An independent approver must approve a pending version.");var vv=await versions.ListAsync(x=>x.PageId==p.PageId,ct);if(vv.Any(x=>x.VersionNo>v.VersionNo))throw new BusinessRuleException("Only the latest version can be approved.");v.ApprovedBy=Actor;p.Status="Published";});}
}
